"""
Returns all possible outcomes for the parking function 1^n
over the set of all labelled graphs on n vertices.
The code computes these outcomes using a bijection to 
involutions, proven by Aditya Khanna.
"""


# This file was *autogenerated* from the file 1^n_graph_counting.sage
from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_0 = Integer(0); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4)
def possible_outcomes(n):
    invs = []
    for p in Permutations(n-_sage_const_1 ):
        if p.inverse() == p:
            invs.append(p)

    outcomes = []
    for inv in invs:
        cyc = inv.to_cycles()
        out = [_sage_const_1 ]
        for tr in cyc:
            if len(tr) == _sage_const_2 :
                out.append(tr[_sage_const_1 ]+_sage_const_1 )
            out.append(tr[_sage_const_0 ]+_sage_const_1 )
        outcomes.append(out)
    return outcomes

"""
Given an outcome of the friendship parking function 1^n, returns
the number of labelled graphs on n vertices on which 1^n is
a friendship parking function with that outcome.

This function cannot return the graphs themselves - while it 
is possible to adapt it to do so, that adaptation is complicated, 
and the number of such graphs grows very quickly to be useful.

The function relies on a proof of the count by counting "adjacencies"
in the outcome, and the logic reflects that. The logic for finding
the entry to start counting from, while efficient, is difficult to 
read and might benefit from a more straightforward rewrite.
"""
def graphs_per_outcome(out):
    # Initialization adjusted to not have to consider car 1
    n = len(out)
    street = [_sage_const_0 ]*n
    street[_sage_const_0 ] = _sage_const_1 
    queue = sorted(list(zip(out, list(range(n)))))[_sage_const_1 :]
    claws = []

    for car, pos in queue:
        old_pos = pos
        street[pos] = car
        # Looking for first Fibonacci start (incomprehensible :C)
        if pos == _sage_const_1  or (pos == _sage_const_2  and street[_sage_const_1 ] == _sage_const_0 ):
            cars_behind = sum([int(street[i] < car and street[i] != _sage_const_0 ) for i in range(old_pos+_sage_const_2 , n)])
            claws.append(_sage_const_2 **cars_behind)
            continue
        if street[pos-_sage_const_1 ] >= _sage_const_2  and street[pos-_sage_const_2 ] == _sage_const_0 :
            if street[pos-_sage_const_3 ] == _sage_const_1 :
                cars_behind = sum([int(street[i] < car and street[i] != _sage_const_0 ) for i in range(old_pos+_sage_const_2 , n)])
                claws.append(_sage_const_2 **cars_behind)
                continue
            pos -= _sage_const_1 
        if street[pos-_sage_const_1 ] == _sage_const_0  and street[pos-_sage_const_2 ] != _sage_const_1 :
            # go 3 back if there is a car there, go 4 back if there isn't
            pos -= (_sage_const_3  + int(street[pos-_sage_const_3 ] == _sage_const_0 )) 
        else:
            pos -= _sage_const_2 

        # Walking gaps for Fibonacci (no gap is F3 = 2)
        fib = _sage_const_0 
        gap = False
        for i in range(pos, -_sage_const_1 , -_sage_const_1 ):
            if not gap: # and street[i] != 0 (redundant)
                fib += _sage_const_1 
                gap = True
            elif gap and street[i] == _sage_const_0 :
                gap = False
            elif gap and street[i] != _sage_const_0 :
                claws.append(fibonacci(fib + _sage_const_2 ))
                fib = _sage_const_1 
                gap = True
        claws.append(fibonacci(fib + _sage_const_2 ))

        # Get the cars you never interact with - all 2 because the connection is free
        cars_behind = sum([int(street[i] < car and street[i] != _sage_const_0 ) for i in range(old_pos+_sage_const_2 , n)])
        claws.append(_sage_const_2 **cars_behind)
    return prod(claws)

total = []
outcomes = possible_outcomes(_sage_const_4 )
for out in outcomes:
    count = graphs_per_outcome(out)
    print(out, count)
    total.append(count)
print(sum(total))

